import java.util.StringTokenizer

fun main() {
    val br = System.`in`.bufferedReader()
    val st = StringTokenizer(br.readLine())
    val people = st.nextToken().toInt()
    var seconds = st.nextToken().toInt()
    var prev = br.readLine()
    var cur = StringBuilder()

    while (seconds > 0) {
        var idx = 0
        while (idx < people) {
            if (idx == people - 1) {
                cur.append(prev[idx])
                break
            }
            if (prev[idx] == 'B' && prev[idx + 1] == 'G') {
                cur.append('G')
                cur.append('B')
                idx += 1
            } else {
                cur.append(prev[idx])
            }
            idx += 1
        }
        prev = cur.toString()
        cur = StringBuilder()
        seconds -= 1
    }

    println(prev)
}

